SELECT r.graph_relation, r.direction, r.mode, r.status, d.document_id, d.revision, r.source_id AS source_endpoint, r.target_id AS target_endpoint, o1.missing AS source_missing, o2.missing AS target_missing, sk.missing AS sketch_missing FROM main.cad_relation AS r JOIN main.cad_object AS o1 ON r.source_id = o1.object_id JOIN main.cad_object AS o2 ON r.target_id = o2.object_id JOIN main.cad_document AS d ON o1.object_id = d.selected_object_id LEFT JOIN main.cad_sketch_owner AS sk ON r.source_id = sk.object_id WHERE r.source_id = 'profile';
